package com.socialhub.security;

import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.*; import com.socialhub.user.entity.User; import org.springframework.stereotype.Service; import org.springframework.beans.factory.annotation.Value;
@Service public class JwtService { private final SecretKey key; private final long expiration; public JwtService(@Value("${app.jwt-secret}") String secret,@Value("${app.jwt-expiration-minutes:1440}") long expiration){if(secret==null || secret.getBytes(StandardCharsets.UTF_8).length<32)throw new IllegalStateException("JWT_SECRET must contain at least 32 UTF-8 bytes");this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.expiration=expiration;} public String create(User user){Date now=new Date();return Jwts.builder().subject(user.id.toString()).issuedAt(now).expiration(new Date(now.getTime()+expiration*60000)).signWith(key).compact();} public UUID verify(String token){return UUID.fromString(Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject());} }
